    @QueryHandler
    public List<FeatureSet> handle( FindAllFeatureSetQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindFeatureSet,
 * but only if the id matches
 *
 * @param		entity	FeatureSet
 */
	protected void emitFindFeatureSet( FeatureSet entity ) {
		LOGGER.info("handling emitFindFeatureSet" );
		
	    queryUpdateEmitter.emit(FindFeatureSetQuery.class,
	                            query -> query.getFilter().getFeatureSetId().equals(entity.getFeatureSetId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFeatureSet
	 * 
	 * @param		entity	FeatureSet
	 */
	protected void emitFindAllFeatureSet( FeatureSet entity ) {
		LOGGER.info("handling emitFindAllFeatureSet" );
		
	    queryUpdateEmitter.emit(FindAllFeatureSetQuery.class,
	                            query -> true,
	                            entity);
	}

